interface IBaseTradingViewPerpsV2Props {
  symbol: string;
  // Spot-only normalized labels; perp omits and the TV side falls back to symbol.
  displayPair?: string;
  displayCoin?: string;
  userAddress: IHex | undefined | null;
  enablePerpsTradingUi?: boolean;
  enableNativeChartControls?: boolean;
  isNativeChartFullscreen?: boolean;
  onNativeChartFullscreenChange?: (isFullscreen: boolean) => void;
  onChartSwitch?: () => void;
  webviewKey?: string;
  reloadOnSymbolChange?: boolean;
  collapseChartExpandSignal?: number;
  onLoadEnd?: () => void;
  onTradeUpdate?: (trade: ITradeEvent) => void;
  onTouchScroll?: (deltaY: number) => void;
  onInteractionOverlayOpenChange?: (isOpen: boolean) => void;
}

export type ITradingViewPerpsV2Props = IBaseTradingViewPerpsV2Props &
  IStackStyle;

const PERPS_NATIVE_CHART_CONTROL_DISABLED_FEATURES = [
  TRADING_VIEW_DISABLED_FEATURES.TIMEFRAME_SELECTOR,
  TRADING_VIEW_DISABLED_FEATURES.TIME_SCALE,
  TRADING_VIEW_DISABLED_FEATURES.SETTINGS,
  TRADING_VIEW_DISABLED_FEATURES.FULLSCREEN,
  TRADING_VIEW_DISABLED_FEATURES.LAYOUT_TOGGLE,
] as const;

// Dynamic params sync hook - symbol changes sync via message instead of WebView reload
const useSymbolSync = ({
  webRef,
  symbol,
  displayPair,
  displayCoin,
  isChartReady,
  enabled,
  syncOnReady = enabled,
}: {
  webRef: React.RefObject<IWebViewRef | null>;
  symbol: string;
  displayPair: string | undefined;
  displayCoin: string | undefined;
  isChartReady: boolean;
  enabled: boolean;
  syncOnReady?: boolean;
}) => {
  const prevParamsRef = useRef({
    displayCoin,
    displayPair,
    symbol,
  });
  const readySyncKeyRef = useRef<string | null>(null);

  const sendSymbolChange = useCallback(
    ({ force }: { force: boolean }) => {
      webRef.current?.sendMessageViaInjectedScript({
        type: 'SYMBOL_CHANGE',
        payload: {
          symbol,
          displayPair,
          displayCoin,
          force,
        },
      });
    },
    [displayCoin, displayPair, symbol, webRef],
  );

  useEffect(() => {
    if (!enabled) {
      prevParamsRef.current = {
        displayCoin,
        displayPair,
        symbol,
      };
      return;
    }

    const prevParams = prevParamsRef.current;
    const hasSymbolChanged = prevParams.symbol !== symbol;
    const hasDisplayParamsChanged =
      prevParams.displayPair !== displayPair ||
      prevParams.displayCoin !== displayCoin;

    if ((hasSymbolChanged || hasDisplayParamsChanged) && webRef.current) {
      // Sync symbol changes via message communication instead of WebView reload
      sendSymbolChange({ force: hasSymbolChanged });

      prevParamsRef.current = {
        displayCoin,
        displayPair,
        symbol,
      };
    }
  }, [displayCoin, displayPair, enabled, sendSymbolChange, symbol, webRef]);

  // Re-sync symbol when chart becomes ready to catch messages lost during iframe load
  useEffect(() => {
    if (!syncOnReady) {
      readySyncKeyRef.current = null;
      return;
    }

    if (!isChartReady) {
      readySyncKeyRef.current = null;
      return;
    }

    const readySyncKey = `${symbol}:${displayPair ?? ''}:${displayCoin ?? ''}`;
    if (readySyncKeyRef.current === readySyncKey || !webRef.current) {
      return;
    }

    sendSymbolChange({ force: false });
    readySyncKeyRef.current = readySyncKey;
  }, [
    displayCoin,
    displayPair,
    isChartReady,
    sendSymbolChange,
    symbol,
    syncOnReady,
    webRef,
  ]);
};

// WebView Memoized component to prevent unnecessary re-renders
const WebViewMemoized = memo(
  ({
    src,
    customReceiveHandler,
    onWebViewRef,
    onShouldStartLoadWithRequest,
    ...otherProps
  }: Omit<
    IWebViewProps,
    | 'src'
    | 'customReceiveHandler'
    | 'onWebViewRef'
    | 'onShouldStartLoadWithRequest'
  > & {
    src: string;
    customReceiveHandler: IJsBridgeReceiveHandler;
    onWebViewRef: (ref: IWebViewRef | null) => void;
    onShouldStartLoadWithRequest?: (event: WebViewNavigation) => boolean;
  }) => (
    <WebView
      src={src}
      customReceiveHandler={customReceiveHandler}
      onWebViewRef={onWebViewRef}
      onShouldStartLoadWithRequest={onShouldStartLoadWithRequest}
      {...otherProps}
    />
  ),
  (prevProps, nextProps) => {
    // Only re-render if critical props change
    return (
      prevProps.src === nextProps.src &&
      prevProps.customReceiveHandler === nextProps.customReceiveHandler &&
      prevProps.containerStyle === nextProps.containerStyle &&
      prevProps.style === nextProps.style &&
      prevProps.onShouldStartLoadWithRequest ===
        nextProps.onShouldStartLoadWithRequest
    );
  },
);

WebViewMemoized.displayName = 'WebViewMemoized';

const hideTradingViewBuiltInLoadingScript = `
  ;(function() {
    var styleText = [
      '#loading-indicator',
      '.loading-indicator',
      '.tv-spinner',
      '.spinner.tv-spinner'
    ].join(',') + '{display:none!important;visibility:hidden!important;opacity:0!important;}';

    function applyStyle(doc) {
      try {
        if (!doc || !doc.documentElement) {
          return;
        }
        if (!doc.getElementById('onekey-hide-tradingview-loading')) {
          var style = doc.createElement('style');
          style.id = 'onekey-hide-tradingview-loading';
          style.textContent = styleText;
          doc.documentElement.appendChild(style);
        }
      } catch (error) {
        // noop
      }
    }

    function applyToFrames() {
      applyStyle(document);
      try {
        var frames = document.querySelectorAll('iframe');
        for (var i = 0; i < frames.length; i += 1) {
          var frame = frames[i];
          applyStyle(frame.contentDocument);
        }
      } catch (error) {
        // noop
      }
    }

    applyToFrames();
    var observer = new MutationObserver(applyToFrames);
    observer.observe(document.documentElement, {
      childList: true,
      subtree: true
    });
    var intervalId = setInterval(applyToFrames, 100);
    setTimeout(function() {
      clearInterval(intervalId);
      observer.disconnect();
    }, 5000);
  })();
  true;
`;

export function TradingViewPerpsV2(
  props: ITradingViewPerpsV2Props & WebViewProps,
) {
  const {
    symbol,
    displayPair,
    displayCoin,
    userAddress,
    enablePerpsTradingUi = false,
    enableNativeChartControls = false,
    isNativeChartFullscreen,
    onNativeChartFullscreenChange,
    onChartSwitch,
    reloadOnSymbolChange = false,
    collapseChartExpandSignal,
    onLoadEnd,
    onTradeUpdate,
    onTouchScroll,
    onInteractionOverlayOpenChange,
    webviewKey,
    ...stackStyle
  } = props;
  const [, setMounted] = usePerpsCandlesWebviewMountedAtom();
  const webRef = useRef<IWebViewRef | null>(null);
  const {
    initialInterval,
    isRestoringInterval,
    reset: resetNativeChartControls,
    onIntervalConfigChange,
    onNativeChartControlsConfigChange,
    controlsProps,
  } = usePerpsNativeChartControls({
    enabled: enableNativeChartControls,
    webRef,
  });
  const theme = useThemeVariant();
  const latestThemeRef = useRef(theme);
  latestThemeRef.current = theme;
  const onLoadEndRef = useRef(onLoadEnd);
  onLoadEndRef.current = onLoadEnd;
  const themeColors = useTheme();
  const tradingViewBackgroundColor = themeColors.bgApp.val;
  const actions = useHyperliquidActions();
  const ensureTradingEnabled = useEnsureTradingEnabled();
  const intl = useIntl();
  const { restoreNonce } = useNetworkRestore();

  // szDecimals comes from the active instrument's universe — the same scoped
  // atom that drives `symbol`, so coin and precision update together (no chart-
  // symbol divergence) and reactively once meta loads. getSymbolMeta(symbol)
  // can't resolve spot, whose coin is a plain base name (OK-56902/56903).
  const [activeTradeInstrument] = useActiveTradeInstrumentAtom();
  const szDecimals =
    activeTradeInstrument.mode === 'spot'
      ? activeTradeInstrument.universe?.baseSzDecimals
      : activeTradeInstrument.universe?.szDecimals;
  const _webviewKey = useMemo(() => {
    const themeKey =
      platformEnv.isDesktop || platformEnv.isNative ? '' : `${theme}-`;
    return `${themeKey}${webviewKey || ''}${
      reloadOnSymbolChange ? `-${symbol}` : ''
    }`;
  }, [reloadOnSymbolChange, symbol, theme, webviewKey]);
  const [chartLinesReadyWebviewKey, setChartLinesReadyWebviewKey] = useState<
    string | null
  >(null);
  const [chartContentReadyWebviewKey, setChartContentReadyWebviewKey] =
    useState<string | null>(null);
  const hasPerpsReadyRef = useRef(false);
  const lastHandledRestoreNonceRef = useRef(0);
  const chartOrderDialogRef = useRef<IDialogInstance | null>(null);

  const closeChartOrderDialog = useCallback(() => {
    const dialog = chartOrderDialogRef.current;
    chartOrderDialogRef.current = null;
    if (dialog?.isExist()) {
      void dialog.close();
    }
  }, []);

  const isChartLinesReady = chartLinesReadyWebviewKey === _webviewKey;
  const isChartContentReady = chartContentReadyWebviewKey === _webviewKey;

  // OK-59100: on iOS this flag gates both the header pan gesture and the tab
  // scroller, and nothing ever reset it — a stray `open` arriving before the
  // chart is live never receives its matching `close` and locks scrolling for
  // the rest of the session (fail-closed). Accept `open` only once the chart
  // reports ready; a reload invalidates any pending open state anyway.
  const isChartContentReadyRef = useRef(isChartContentReady);
  isChartContentReadyRef.current = isChartContentReady;
  const guardedInteractionOverlayOpenChange = useCallback(
    (isOpen: boolean) => {
      if (isOpen && !isChartContentReadyRef.current) {
        return;
      }
      onInteractionOverlayOpenChange?.(isOpen);
    },
    [onInteractionOverlayOpenChange],
  );
  // Any transition out of ready (reload, navigation, render-process loss)
  // discards overlay state the chart can no longer close on its own.
  useEffect(() => {
    if (!isChartContentReady) {
      onInteractionOverlayOpenChange?.(false);
    }
  }, [isChartContentReady, onInteractionOverlayOpenChange]);

  const prevWebviewKeyRef = useRef(_webviewKey);
  useEffect(() => {
    if (prevWebviewKeyRef.current !== _webviewKey) {
      // A new WebView instance must prove perpsReady before app-side recovery
      // can stay hands-off.
      hasPerpsReadyRef.current = false;
      setChartLinesReadyWebviewKey(null);
      setChartContentReadyWebviewKey(null);
      resetNativeChartControls();
      prevWebviewKeyRef.current = _webviewKey;
    }
  }, [_webviewKey, resetNativeChartControls]);

  useEffect(() => {
    setMounted({ mounted: true });
    return () => {
      setMounted({ mounted: false });
      closeChartOrderDialog();
    };
  }, [closeChartOrderDialog, setMounted]);

  // Warm the allMids cache AND refresh the persisted scale before the chart's
  // resolveSymbol asks, so a cold start never waits on the REST fallback and
  // the persisted scale keeps a refresh path even when the bridge request is
  // skipped by future TV builds.
  useEffect(() => {
    void backgroundApiProxy.serviceHyperliquid
      .getTradingviewPriceScale({ symbol })
      .catch(() => undefined);
  }, [symbol]);

  const latestSymbolRef = useRef(symbol);
  latestSymbolRef.current = symbol;

  // A refreshed scale that differs from the one the chart resolved with needs
  // a forced re-resolve, or the wrong precision would persist all session.
  useEffect(() => {
    const handler = (payload: { symbol: string; priceScale: number }) => {
      if (payload.symbol !== latestSymbolRef.current) {
        return;
      }
      webRef.current?.sendMessageViaInjectedScript({
        type: 'SYMBOL_CHANGE',
        payload: {
          symbol: payload.symbol,
          displayPair,
          displayCoin,
          force: true,
        },
      });
    };
    appEventBus.on(EAppEventBusNames.PerpsTvPriceScaleRefreshed, handler);
    return () => {
      appEventBus.off(EAppEventBusNames.PerpsTvPriceScaleRefreshed, handler);
    };
  }, [displayCoin, displayPair]);
  const prevSymbolRef = useRef(symbol);
  useEffect(() => {
    if (prevSymbolRef.current !== symbol) {
      closeChartOrderDialog();
      prevSymbolRef.current = symbol;
    }
  }, [closeChartOrderDialog, symbol]);

  const { handleNavigation } = useNavigationHandler();

  // Optimization: Static URL with only initialization params to avoid WebView reload
  // Memoize additionalParams to prevent useTradingViewUrl from regenerating URL
  const staticUrlSymbol = useMemo(
    () => symbol,
    // Symbol-only changes are sent through SYMBOL_CHANGE. Recompute only when
    // the WebView is intentionally re-keyed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [_webviewKey],
  );
  const urlSymbol = reloadOnSymbolChange ? symbol : staticUrlSymbol;
  const additionalParams = useMemo(
    () => ({
      symbol: urlSymbol,
      type: 'perps' as const,
      storageNamespace: 'perps' as const,
      enablePerpsTradingUi: enablePerpsTradingUi ? '1' : '0',
      ...(enableNativeChartControls ? { nativeChartControls: '1' } : {}),
      ...(initialInterval ? { initialResolution: initialInterval } : {}),
    }),
    [
      enableNativeChartControls,
      enablePerpsTradingUi,
      initialInterval,
      urlSymbol,
    ],
  );

  const { finalUrl: staticTradingViewUrl, timezone } = useTradingViewUrl({
    additionalParams,
    disabledFeatures: enableNativeChartControls
      ? PERPS_NATIVE_CHART_CONTROL_DISABLED_FEATURES
      : undefined,
    theme,
  });
  const isSpotDisplayNameSyncRequired =
    reloadOnSymbolChange && (!!displayPair || !!displayCoin);
  const tradingViewWebViewStyleProps = useMemo(
    () => ({
      containerStyle: { backgroundColor: tradingViewBackgroundColor },
      style: { backgroundColor: tradingViewBackgroundColor },
    }),
    [tradingViewBackgroundColor],
  );

  // Optimization: Dynamic symbol parameter sync mechanism
  useSymbolSync({
    webRef,
    symbol,
    displayPair,
    displayCoin,
    isChartReady: reloadOnSymbolChange
      ? isChartContentReady
      : isChartLinesReady,
    enabled: !reloadOnSymbolChange,
    syncOnReady: !reloadOnSymbolChange || isSpotDisplayNameSyncRequired,
  });

  const processedCollapseChartExpandSignalRef = useRef(0);

  useEffect(() => {
    if (
      !collapseChartExpandSignal ||
      collapseChartExpandSignal ===
        processedCollapseChartExpandSignalRef.current
    ) {
      return;
    }

    if (!isChartContentReady || !webRef.current) {
      return;
    }

    processedCollapseChartExpandSignalRef.current = collapseChartExpandSignal;

    const syncChartCollapsed = () => {
      webRef.current?.sendMessageViaInjectedScript({
        type: MESSAGE_TYPES.PERPS_TV_CHART_EXPAND_SYNC,
        payload: { expanded: false },
      });
    };

    syncChartCollapsed();
    const retryTimer = setTimeout(syncChartCollapsed, 250);

    return () => {
      clearTimeout(retryTimer);
    };
  }, [collapseChartExpandSignal, isChartContentReady]);

  const pendingRecoverRef = useRef(false);

  useEffect(() => {
    const handler = () => {
      if (isChartLinesReady && webRef.current) {
        webRef.current.sendMessageViaInjectedScript({
          type: 'FORCE_RECOVER_WS',
        });
      } else {
        pendingRecoverRef.current = true;
      }
    };
    appEventBus.on(EAppEventBusNames.PerpsWebSocketRecovered, handler);
    return () => {
      appEventBus.off(EAppEventBusNames.PerpsWebSocketRecovered, handler);
    };
  }, [isChartLinesReady, webRef]);

  useEffect(() => {
    if (isChartLinesReady && pendingRecoverRef.current) {
      pendingRecoverRef.current = false;
      webRef.current?.sendMessageViaInjectedScript({
        type: 'FORCE_RECOVER_WS',
      });
    }
  }, [isChartLinesReady, webRef]);

  useEffect(() => {
    if (restoreNonce <= 0) {
      return;
    }
    if (lastHandledRestoreNonceRef.current === restoreNonce) {
      return;
    }

    lastHandledRestoreNonceRef.current = restoreNonce;

    if (!hasPerpsReadyRef.current) {
      setChartLinesReadyWebviewKey(null);
      setChartContentReadyWebviewKey(null);
      webRef.current?.reload();
    }
  }, [restoreNonce]);

  const onChartLinesReady = useCallback(() => {
    syncTradingViewTheme(webRef.current, latestThemeRef.current);
    hasPerpsReadyRef.current = true;
    setChartContentReadyWebviewKey(_webviewKey);
    setChartLinesReadyWebviewKey(_webviewKey);
  }, [_webviewKey]);

  const onChartReady = useCallback(() => {
    syncTradingViewTheme(webRef.current, latestThemeRef.current);
    setChartContentReadyWebviewKey(_webviewKey);
  }, [_webviewKey]);

  const onOrderCancel = useCallback(
    async (payload: ITVOrderCancelPayload) => {
      const oid = Number.parseInt(payload.orderId ?? '', 10);
      if (!Number.isFinite(oid)) return;
      if (!enablePerpsTradingUi) return;

      // Message handler invokes this without await — swallow rejections to
      // avoid leaking them as unhandled; errors are already surfaced via
      // the enable-trading flow or cancelChartOrder.
      try {
        await ensureTradingEnabled();
        await actions.current.cancelChartOrder({ oid });
      } catch {
        // intentional: toast owns the user-facing message
      }
    },
    [actions, enablePerpsTradingUi, ensureTradingEnabled],
  );

  const onOrderDraftCreate = useCallback(
    (_payload: ITVOrderDraftCreatePayload) => {
      // No-op kept for version skew: an old chart still emitting the legacy
      // method must not place an order (placement moved to onChartOrderIntent).
    },
    [],
  );

  const onChartOrderIntent = useCallback(
    async (payload: ITVChartOrderIntentPayload) => {
      if (!enablePerpsTradingUi) return;

      // Fire-and-forget handler: self-own errors to avoid unhandled rejections.
      try {
        if (payload.intent === 'limitEntry') {
          const isCurrentSymbolIntent =
            payload.symbol === latestSymbolRef.current;
          if (!isCurrentSymbolIntent) return;
          closeChartOrderDialog();
          chartOrderDialogRef.current = showLimitOrderDialog({
            symbol: payload.symbol,
            price: payload.price,
            displayPair: isCurrentSymbolIntent ? displayPair : undefined,
            displayCoin: isCurrentSymbolIntent ? displayCoin : undefined,
            intl,
          });
          return;
        }
        if (payload.intent === 'positionTpSl') {
          const meta =
            await backgroundApiProxy.serviceHyperliquid.getSymbolMeta({
              coin: payload.symbol,
            });
          if (!meta) return;
          if (payload.symbol !== latestSymbolRef.current) return;
          closeChartOrderDialog();
          chartOrderDialogRef.current = showSetTpslDialog({
            coin: payload.symbol,
            szDecimals: meta.universe?.szDecimals ?? 0,
            assetId: meta.assetId,
            presetTriggerPrice: payload.price,
            presetTpsl: payload.tpsl,
            intl,
          });
        }
      } catch (error) {
        console.error('[TradingViewPerpsV2] onChartOrderIntent failed:', error);
      }
    },
    [
      closeChartOrderDialog,
      displayCoin,
      displayPair,
      enablePerpsTradingUi,
      intl,
    ],
  );

  const onOrderPriceUpdate = useCallback(
    async (payload: ITVOrderPriceUpdatePayload) => {
      const oid = Number.parseInt(payload.orderId ?? '', 10);
      if (!Number.isFinite(oid)) return;
      if (!enablePerpsTradingUi) {
        webRef.current?.sendMessageViaInjectedScript({
          type: MESSAGE_TYPES.PERPS_TV_ORDER_PRICE_UPDATE_REJECTED,
          payload: {
            requestId: payload.requestId,
            lineId: payload.lineId,
            symbol: payload.symbol,
            orderId: payload.orderId,
          },
        });
        return;
      }

      try {
        await ensureTradingEnabled();
        await actions.current.amendChartOrder({
          coin: payload.symbol,
          oid,
          newPrice: payload.price,
        });
      } catch {
        webRef.current?.sendMessageViaInjectedScript({
          type: MESSAGE_TYPES.PERPS_TV_ORDER_PRICE_UPDATE_REJECTED,
          payload: {
            requestId: payload.requestId,
            lineId: payload.lineId,
            symbol: payload.symbol,
            orderId: payload.orderId,
          },
        });
      }
    },
    [actions, enablePerpsTradingUi, ensureTradingEnabled, webRef],
  );

  const { customReceiveHandler } = usePerpsTradingViewMessageHandler({
    symbol,
    userAddress,
    webRef,
    onChartReady,
    onChartLinesReady,
    onOrderCancel,
    onOrderDraftCreate,
    onOrderPriceUpdate,
    onChartOrderIntent,
    onTouchScroll,
    onInteractionOverlayOpenChange: guardedInteractionOverlayOpenChange,
    onIntervalConfigChange: enableNativeChartControls
      ? onIntervalConfigChange
      : undefined,
    onNativeChartControlsConfigChange: enableNativeChartControls
      ? onNativeChartControlsConfigChange
      : undefined,
  });

  // Chart lines management (liquidation, position, orders)
  useChartLines({
    symbol,
    szDecimals: szDecimals ?? 2,
    userAddress,
    webRef,
    isReady: isChartLinesReady,
  });

  // trade update push
  const { pushTradeUpdate: _pushTradeUpdate } = useTradeUpdates({
    webRef,
    onTradeUpdate,
  });

  const onWebViewRef = useCallback((ref: IWebViewRef | null) => {
    webRef.current = ref;
  }, []);

  useEffect(() => {
    syncTradingViewTheme(webRef.current, theme);
  }, [theme]);

  const handleLoadEnd = useCallback(() => {
    syncTradingViewTheme(webRef.current, latestThemeRef.current);
    onLoadEndRef.current?.();
  }, []);

  const handleLoadStart = useCallback(
    (event?: WebViewNavigationEvent) => {
      // Android emits load-start for same-document history updates, without a new chart-ready event.
      if (platformEnv.isNativeAndroid && event?.nativeEvent.loading === false) {
        return;
      }
      resetNativeChartControls();
      hasPerpsReadyRef.current = false;
      setChartLinesReadyWebviewKey(null);
      setChartContentReadyWebviewKey(null);
    },
    [resetNativeChartControls],
  );

  const handleDidStartNavigation = useCallback<
    NonNullable<IElectronWebViewEvents['onDidStartNavigation']>
  >(
    (event) => {
      if (event.isMainFrame && !event.isInPlace) {
        handleLoadStart();
      }
    },
    [handleLoadStart],
  );

  const onShouldStartLoadWithRequest = useCallback(
    (event: WebViewNavigation) => handleNavigation(event),
    [handleNavigation],
  );
  const showChartLoadingMask =
    !isChartContentReady ||
    (Boolean(controlsProps.nativeChartControlsConfig) && isRestoringInterval);

  return (
    <Stack flex={1} minHeight={0} {...stackStyle}>
      {enableNativeChartControls ? (
        <TradingViewV2ChartControlsContainer
          {...controlsProps}
          isControlsReady={
            isChartContentReady &&
            Boolean(controlsProps.nativeChartControlsConfig)
          }
          chartTypeControlMode="select"
          indicatorControlMode="popover"
          intervalControlMode="popover"
          layoutMode="desktop"
          chartTimezone={timezone}
          isFullscreen={isNativeChartFullscreen}
          onFullscreenChange={onNativeChartFullscreenChange}
          onChartSwitch={onChartSwitch}
        />
      ) : null}
      <Stack position="relative" flex={1} minHeight={0}>
        <WebViewMemoized
          key={_webviewKey}
          src={staticTradingViewUrl}
          containerProps={{ bg: '$bgApp' }}
          containerStyle={tradingViewWebViewStyleProps.containerStyle}
          style={tradingViewWebViewStyleProps.style}
          customReceiveHandler={customReceiveHandler}
          skipBackgroundBridge
          onWebViewRef={onWebViewRef}
          onLoadEnd={handleLoadEnd}
          onLoadStart={handleLoadStart}
          onDidStartNavigation={handleDidStartNavigation}
          onShouldStartLoadWithRequest={onShouldStartLoadWithRequest}
          nativeInjectedJavaScriptBeforeContentLoaded={
            platformEnv.isNativeAndroid
              ? hideTradingViewBuiltInLoadingScript
              : undefined
          }
          allowsBackForwardNavigationGestures={false}
          displayProgressBar={false}
          pullToRefreshEnabled={false}
          scrollEnabled={false}
          bounces={false}
          overScrollMode="never"
          showsHorizontalScrollIndicator={false}
          showsVerticalScrollIndicator={false}
          decelerationRate="normal"
        />

        {showChartLoadingMask ? <TradingViewChartLoadingMask /> : null}

        {platformEnv.isNativeIOS ? (
          <Stack
            position="absolute"
            left={0}
            top={0}
            bottom={0}
            width={12}
            zIndex={1}
            pointerEvents="auto"
          />
        ) : null}
      </Stack>
    </Stack>
  );
}
